// Config — constantes do fluxo GAB-MAIL 1. Nenhuma senha aqui: a senha do e-mail
// mora só na credencial IMAP do n8n.
const cfg = {
  caixa: 'contato@ativeassessoriafinanceira.com.br',
  fuso: 'America/Sao_Paulo',
  // Bases do Notion (API 2022-06-28 usa o id da base, não o do data source)
  recebidasDbId: 'a62d9649-5d3d-4863-97f2-7b5d8b6dfc81',
  crmDbId: '4e84cf3d-6285-83f3-b094-81990f3dd072',
  // Domínios de e-mail pessoal: o cadastro novo leva "(e-mail)" em vez do domínio
  dominiosGenericos: [
    'gmail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com',
    'yahoo.com.br', 'icloud.com', 'uol.com.br', 'bol.com.br', 'terra.com.br',
  ],
  maxConteudo: 1900, // limite do Notion é 2000 por bloco de texto
};

return $input.all().map((item) => ({ json: { ...item.json, cfg }, binary: item.binary }));

// Normaliza e-mail — lê a saída do gatilho IMAP (formato "resolved", do mailparser;
// o formato "simple" também é aceito) e devolve campos únicos para o resto do fluxo.
// Descarta só o que duplicaria registro. E-mail automático não é descartado: vira
// linha "ignorada", sem criar contato.

const limpa = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

function enderecos(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.flatMap(enderecos);
  if (Array.isArray(v.value)) {
    return v.value
      .filter((a) => a && a.address)
      .map((a) => ({ address: a.address.trim(), name: limpa(a.name) }));
  }
  if (typeof v === 'string') {
    // "Fulano <fulano@x.com>, outro@y.com"
    return v.split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/).map((parte) => {
      const m = parte.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
      if (m) return { address: m[2].trim(), name: limpa(m[1]) };
      return { address: parte.trim(), name: '' };
    }).filter((a) => a.address.includes('@'));
  }
  return [];
}

function cabecalho(headers, nome) {
  if (!headers) return '';
  const v = headers[nome] ?? headers[nome.toLowerCase()];
  if (v == null) return '';
  // O n8n guarda a linha inteira ("List-Id: <...>"); tira o nome do cabeçalho
  return String(v).replace(new RegExp('^' + nome + ':\\s*', 'i'), '');
}

function htmlParaTexto(html) {
  return String(html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

// Fica só com a parte nova: corta o histórico citado da resposta
function parteNova(texto) {
  const linhas = String(texto || '').replace(/\r/g, '').split('\n');
  const saida = [];
  for (const linha of linhas) {
    const l = linha.trim();
    if (/^(em|on)\s.+(escreveu|wrote)\s*:$/i.test(l)) break;
    if (/^-{2,}\s*(mensagem original|original message|forwarded message|mensagem encaminhada)/i.test(l)) break;
    if (/^(de|from)\s*:\s.+@/i.test(l) && saida.length > 0) break;
    if (l.startsWith('>')) continue;
    saida.push(linha);
  }
  return saida.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function titulo80(s) {
  const t = limpa(s);
  if (t.length <= 80) return t;
  const corte = t.slice(0, 80);
  const espaco = corte.lastIndexOf(' ');
  return (espaco > 40 ? corte.slice(0, espaco) : corte) + '…';
}

function dataSP(d, fuso) {
  // YYYY-MM-DD no fuso de São Paulo (perto da meia-noite o UTC já virou o dia)
  return new Intl.DateTimeFormat('en-CA', { timeZone: fuso, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}

const saida = [];
for (const item of $input.all()) {
  const j = item.json;
  const cfg = j.cfg;
  const caixa = cfg.caixa.toLowerCase();
  const pasta = j.pasta === 'enviados' ? 'enviados' : 'entrada';
  const headers = j.headers || {};

  const de = enderecos(j.from)[0] || { address: '', name: '' };
  const para = enderecos(j.to);
  const cc = enderecos(j.cc);
  const externos = [...para, ...cc].filter((a) => a.address.toLowerCase() !== caixa);

  const contraparte = pasta === 'enviados' ? externos[0] : de;

  // Descartes: só o que viraria registro duplicado ou sem ninguém do outro lado
  if (pasta === 'entrada' && de.address.toLowerCase() === caixa) continue; // cópia do que já entra por Enviados
  if (!contraparte || !contraparte.address) continue;

  const email = contraparte.address.toLowerCase();
  const local = email.split('@')[0];
  const dominio = email.split('@')[1] || '';

  const automatico =
    pasta === 'entrada' && (
      /^(no-?reply|nao-?responda|naoresponda|mailer-daemon|postmaster|bounces?|notifica(cao|coes)?|notifications?|newsletter)([.+_-]|$)/i.test(local) ||
      /^(auto-generated|auto-replied|auto-notified)/i.test(cabecalho(headers, 'auto-submitted')) ||
      /^(bulk|list|junk)/i.test(cabecalho(headers, 'precedence')) ||
      !!cabecalho(headers, 'list-unsubscribe') ||
      !!cabecalho(headers, 'list-id')
    );

  const assunto = limpa(j.subject) || '(sem assunto)';
  const bruto = j.text || j.textPlain || htmlParaTexto(j.html || j.textHtml);
  const texto = parteNova(bruto) || limpa(bruto);

  const quando = j.date ? new Date(j.date) : new Date();
  const data = isNaN(quando) ? new Date() : quando;

  const anexos = Object.values(item.binary || {}).map((b) => b.fileName).filter(Boolean)
    .concat((j.attachments || []).map((a) => a.filename).filter(Boolean));

  const ehResposta = pasta === 'entrada' && (!!j.inReplyTo || /^\s*(re|res|resp)\s*:/i.test(assunto));

  const messageId = limpa(j.messageId || cabecalho(headers, 'message-id')) ||
    `sem-id:${pasta}:${data.toISOString()}:${email}:${assunto.slice(0, 40)}`;

  const nome = contraparte.name || local;
  const generico = cfg.dominiosGenericos.includes(dominio);

  saida.push({
    json: {
      cfg,
      pasta,
      canal: 'E-mail',
      email,
      emailOriginal: contraparte.address,
      nome,
      nomeCadastro: `${nome} (${generico ? 'e-mail' : dominio})`,
      assunto,
      texto,
      titulo: (pasta === 'enviados' ? '→ ' : ehResposta ? '↩ ' : '') + titulo80(assunto),
      de: de.address,
      para: para.map((a) => a.address).join(', '),
      cc: cc.map((a) => a.address).join(', '),
      outrosDestinatarios: externos.slice(1).map((a) => a.address),
      anexos,
      ehResposta,
      automatico,
      messageId,
      recebidaEm: data.toISOString(),
      dataSP: dataSP(data, cfg.fuso),
    },
  });
}

return saida;

// Resolve contato — decide a quem o e-mail pertence, pelo campo Email do CRM.
// Busca que falhou NUNCA cria contato: sem resposta do Notion não dá para saber se a
// pessoa já existe, e cadastro duplicado é pior que linha sem contato.
const e = $('Um por vez').first(1).json; // saída 1 = loop
const r = $input.first().json;

const buscaOk = Array.isArray(r.results);
const achados = buscaOk ? r.results : [];

let contatoId = achados[0]?.id || '';
let comoIdentificou = '';
if (achados.length === 1) comoIdentificou = 'e-mail';
if (achados.length > 1) comoIdentificou = `e-mail (${achados.length} cadastros com esse e-mail - conferir)`;
if (!buscaOk) comoIdentificou = 'busca no CRM falhou - nao identificado';

const criarContato = buscaOk && achados.length === 0 && !e.automatico;
if (!contatoId && !criarContato) comoIdentificou = comoIdentificou || (e.automatico ? 'e-mail automatico - sem contato' : 'nao identificado');

const hoje = new Intl.DateTimeFormat('pt-BR', { timeZone: e.cfg.fuso }).format(new Date());
const papel = e.pasta === 'enviados' ? 'destinatário' : 'remetente';

return [{
  json: {
    ...e,
    contatoId,
    contatoNovo: false,
    comoIdentificou,
    criarContato,
    corpoContato: criarContato ? {
      parent: { database_id: e.cfg.crmDbId },
      properties: {
        Nome: { title: [{ text: { content: e.nomeCadastro.slice(0, 200) } }] },
        Email: { email: e.email },
        'Situação': { select: { name: 'a_confirmar' } },
        Origem: { rich_text: [{ text: { content:
          `Criado pela captura de e-mail (n8n) em ${hoje}: ${papel} de "${e.assunto.slice(0, 150)}" ` +
          `na caixa ${e.cfg.caixa}. O nome veio do cabeçalho do e-mail - não é identidade confirmada.`,
        } }] },
      },
    } : null,
  },
}];

// Monta registro — corpo da linha em 📥 Recebidas (Canal = E-mail).
// Chega aqui pelos dois lados do IF: com o contato recém-criado (resposta do Notion)
// ou direto, quando não havia o que criar.
const e = $('Resolve contato').first().json;
const r = $input.first().json;

let contatoId = e.contatoId;
let contatoNovo = false;
let comoIdentificou = e.comoIdentificou;
if (e.criarContato) {
  if (r.object === 'page' && r.id) {
    contatoId = r.id;
    contatoNovo = true;
    comoIdentificou = 'contato novo criado (a_confirmar)';
  } else {
    comoIdentificou = 'falhou ao criar o contato - nao identificado';
  }
}

let situacao;
if (e.pasta === 'enviados') situacao = 'enviada por mim';
else if (e.automatico) situacao = 'ignorada';
else if (contatoId && !contatoNovo) situacao = 'vinculada a contato';
else situacao = 'aguardando decisao';

const max = e.cfg.maxConteudo;
const rt = (s) => [{ text: { content: String(s || '').slice(0, max) } }];

let conteudo = e.texto || '(sem texto)';
if (e.anexos.length) conteudo = `📎 ${e.anexos.length} anexo(s): ${e.anexos.join(', ')}\n\n` + conteudo;

// Corpo da página: ficha do e-mail + texto completo em blocos de até 1900 caracteres
const ficha = [
  `De: ${e.de}`,
  `Para: ${e.para}`,
  e.cc ? `Cc: ${e.cc}` : '',
  `Data: ${new Date(e.recebidaEm).toLocaleString('pt-BR', { timeZone: e.cfg.fuso })}`,
  `Identificação: ${comoIdentificou}`,
  `Message-ID: ${e.messageId}`,
].filter(Boolean).join('\n');

const children = [{
  object: 'block', type: 'callout',
  callout: { icon: { type: 'emoji', emoji: '✉️' }, rich_text: rt(ficha) },
}];
const texto = e.texto || '';
for (let i = 0; i < texto.length && children.length < 20; i += max) {
  children.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: rt(texto.slice(i, i + max)) } });
}

const properties = {
  Mensagem: { title: rt(e.titulo) },
  Canal: { select: { name: 'E-mail' } },
  'E-mail': { email: e.email },
  Assunto: { rich_text: rt(e.assunto) },
  Conteudo: { rich_text: rt(conteudo) },
  Tipo: { select: { name: e.anexos.length ? 'documento' : 'texto' } },
  Situacao: { select: { name: situacao } },
  'Recebida em': { date: { start: e.recebidaEm } },
  messageId: { rich_text: rt(e.messageId) },
};
if (contatoId) properties.Contato = { relation: [{ id: contatoId }] };

return [{
  json: {
    ...e,
    contatoId,
    contatoNovo,
    comoIdentificou,
    situacao,
    corpoRegistro: { parent: { database_id: e.cfg.recebidasDbId }, properties, children },
  },
}];

// Confere gravação — nó tolerante a erro esconde falha (lição de 21/09), então o
// resultado é conferido aqui, na resposta do Notion, e não pelo status da execução.
const e = $('Monta registro').first().json;
const r = $input.first().json;
const ok = r.object === 'page' && !!r.id;

return [{
  json: {
    ok,
    registroId: ok ? r.id : '',
    erro: ok ? '' : String(r.error?.message || r.message || JSON.stringify(r).slice(0, 300)),
    pasta: e.pasta,
    email: e.email,
    assunto: e.assunto,
    messageId: e.messageId,
    situacao: e.situacao,
    contatoId: e.contatoId,
    contatoNovo: e.contatoNovo,
    atualizarContato: ok && !!e.contatoId && !e.automatico,
    dataSP: e.dataSP,
  },
}];

// Falhou algum? — roda depois do lote inteiro. Se algum e-mail não foi gravado, a
// execução termina em erro de propósito: o GAB-WPP 0 grava a nota "FALHA em..." com
// esta mensagem, e o e-mail perdido fica nomeado (assunto e remetente).
const todos = $input.all().map((i) => i.json);
const falhas = todos.filter((j) => !j.ok);

if (falhas.length) {
  const lista = falhas.map((f) => `- ${f.pasta}: "${f.assunto}" (${f.email}) -> ${f.erro}`).join('\n');
  throw new Error(`${falhas.length} de ${todos.length} e-mail(s) nao gravados em Recebidas:\n${lista}`);
}

return [{
  json: {
    gravados: todos.length,
    contatosNovos: todos.filter((j) => j.contatoNovo).length,
    porSituacao: todos.reduce((acc, j) => ({ ...acc, [j.situacao]: (acc[j.situacao] || 0) + 1 }), {}),
  },
}];
